import { createGlobalStyle } from 'styled-components'

export const cores = {
  branco: '#E66767',
  preto: '#111',
  cinza: '#FFEBD9',
  verde: '#10AC84',
  cinzaClaro: '#A3A3A3'
}

export const GlobalCss = createGlobalStyle`
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: Roboto, sans-serif;
    list-style: none;
  }
  body{
    background-color: ${cores.preto};
    color: ${cores.branco};
    padding-top: 24px;
  }

  .container{
    max-width: 1366px;
  width: 100%;
  margin: 0 auto;
  margin-bottom: 24px;
  }
  `
